            if 0 <= c < n:
                out[r][c] = 2
    # A diagonal, period-four pattern of 1s begins below the top two rows.
    for r in range(3, n):
        for c in range(n):
            if seed - r < c < seed + r and (c - r) % 4 == 2 and out[r][c] == 0:
                out[r][c] = 1
    return out

